package com.meddibuddy.auth;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;public AuthController(AuthService auth){this.auth=auth;}public record RegisterRequest(@NotBlank String name,@NotBlank @Email String email,@NotBlank @Size(min=8,max=72) String password){}public record LoginRequest(@NotBlank @Email String email,@NotBlank String password){}@PostMapping("/register") public AuthService.Session register(@Valid @RequestBody RegisterRequest r){return auth.register(r.name(),r.email(),r.password());}@PostMapping("/login") public AuthService.Session login(@Valid @RequestBody LoginRequest r){return auth.login(r.email(),r.password());}}
